INSERT INTO XXLGE_EXPORT_INFO (
    session_id,
    created_by,
    creation_date,
    seq_no,
    character_set_name,
    attribute1,

   attribute${index + 2}

)
  SELECT *
    FROM (
          SELECT #{exportSsessionId}
               , #{USER_SESSION.applicationUserId}
               , SYSDATE
               , 1 AS seq_no
               , 'KO16KSC5601'
               , 'Error Message' AS error_message,

               attribute${index + 1}

            FROM LGCOM_IMPORT_N
           WHERE session_id = #{sessionId}
             AND seq_no     = 1
             AND attribute199 IS NULL
          UNION ALL
          SELECT #{exportSsessionId}
               , #{USER_SESSION.applicationUserId}
               , SYSDATE
               , 1 AS seq_no
               , 'KO16KSC5601'
               , attribute200 AS error_message,

               attribute${index + 1}

            FROM LGCOM_IMPORT_N
           WHERE session_id   = #{sessionId}
             AND attribute199 = 'H'
          UNION ALL
          SELECT #{exportSsessionId}
               , #{USER_SESSION.applicationUserId}
               , SYSDATE
               , seq_no
               , 'KO16KSC5601'
               , ATTRIBUTE200 AS error_message,

               attribute${index + 1}

            FROM LGCOM_IMPORT_N
           WHERE session_id   = #{sessionId}
             AND attribute199 = 'Y'
         )
ORDER BY SEQ_NO
